package com.alchaligner;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(AlchAlignerConfig.GROUP)
public interface AlchAlignerConfig extends Config
{
	String GROUP = "alchaligner";

	@ConfigItem(
		keyName = "lowAlchemy",
		name = "Allow Low Level Alchemy",
		description = "Also show the overlay from 21 Magic using Low Level Alchemy. High Level Alchemy is used from 55 Magic.",
		warning = "Low Level Alchemy gives far fewer coins than High Level Alchemy. Only enable this if you are below 55 Magic.",
		position = 0
	)
	default boolean lowAlchemy()
	{
		return false;
	}

	@Range(max = 200)
	@Units(Units.PIXELS)
	@ConfigItem(
		keyName = "nearbyRange",
		name = "Nearby range",
		description = "Only show inventory slots within this distance of the alchemy spell. 0 shows only the slots the spell covers.",
		position = 1
	)
	default int nearbyRange()
	{
		return 10;
	}

	@Alpha
	@ConfigItem(
		keyName = "slotFillColor",
		name = "Slot fill",
		description = "Fill colour of each inventory slot's clickable area",
		position = 2
	)
	default Color slotFillColor()
	{
		return new Color(0, 255, 255, 25);
	}

	@Alpha
	@ConfigItem(
		keyName = "slotBorderColor",
		name = "Slot border",
		description = "Outline colour of each inventory slot's clickable area",
		position = 3
	)
	default Color slotBorderColor()
	{
		return new Color(0, 255, 255, 90);
	}

	@ConfigItem(
		keyName = "highlightTargetSlot",
		name = "Highlight target slots",
		description = "Highlight the part of each inventory slot covered by the alchemy spell. Large spell icons (e.g. with spell filtering) can cover several slots.",
		position = 4
	)
	default boolean highlightTargetSlot()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "targetSlotColor",
		name = "Target slots",
		description = "Colour of the inventory slot areas covered by the alchemy spell",
		position = 5
	)
	default Color targetSlotColor()
	{
		return new Color(255, 255, 0, 70);
	}
}

package com.alchaligner;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * While the spellbook is open, draws where the inventory slots near the alchemy spells
 * will be clickable once the game switches back to the inventory.
 * Slot positions are remembered from the last frame the inventory was visible.
 */
class AlchAlignerOverlay extends Overlay
{
	private final Client client;
	private final AlchAlignerPlugin plugin;
	private final AlchAlignerConfig config;

	private final List<Rectangle> slots = new ArrayList<>();

	@Inject
	AlchAlignerOverlay(Client client, AlchAlignerPlugin plugin, AlchAlignerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void clearSlots()
	{
		slots.clear();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget inventory = client.getWidget(InterfaceID.Inventory.ITEMS);
		if (inventory != null && !inventory.isHidden())
		{
			rememberSlots(inventory);
			return null;
		}

		Widget spellbook = client.getWidget(InterfaceID.MagicSpellbook.UNIVERSE);
		if (spellbook == null || spellbook.isHidden() || slots.isEmpty())
		{
			return null;
		}

		List<Rectangle> spells = getSpellBounds();
		if (spells.isEmpty())
		{
			return null;
		}

		int range = config.nearbyRange();
		Color targetColor = config.targetSlotColor();
		Color targetBorderColor = new Color(targetColor.getRGB());

		for (Rectangle slot : slots)
		{
			if (!isNearAnySpell(slot, spells, range))
			{
				continue;
			}

			graphics.setColor(config.slotFillColor());
			graphics.fill(slot);

			// A large spell icon (e.g. with spell filtering) can cover several slots.
			// Only the overlap is where a click hits both the spell and that slot.
			boolean covered = false;
			if (config.highlightTargetSlot())
			{
				graphics.setColor(targetColor);
				for (Rectangle spell : spells)
				{
					Rectangle overlap = slot.intersection(spell);
					if (!overlap.isEmpty())
					{
						graphics.fill(overlap);
						covered = true;
					}
				}
			}

			graphics.setColor(covered ? targetBorderColor : config.slotBorderColor());
			graphics.draw(slot);
		}

		return null;
	}

	private static boolean isNearAnySpell(Rectangle slot, List<Rectangle> spells, int range)
	{
		for (Rectangle spell : spells)
		{
			Rectangle nearby = new Rectangle(spell);
			nearby.grow(range, range);
			if (nearby.intersects(slot))
			{
				return true;
			}
		}
		return false;
	}

	private void rememberSlots(Widget inventory)
	{
		Widget[] items = inventory.getDynamicChildren();
		Point origin = inventory.getCanvasLocation();
		if (items == null || origin == null || origin.getX() < 0)
		{
			return;
		}

		// Empty slots aren't drawn, so their own bounds are (-1, -1). Their layout position
		// within the inventory is still set, so place every slot relative to the inventory.
		slots.clear();
		for (Widget item : items)
		{
			slots.add(new Rectangle(
				origin.getX() + item.getRelativeX(),
				origin.getY() + item.getRelativeY(),
				item.getWidth(),
				item.getHeight()));
		}
	}

	private List<Rectangle> getSpellBounds()
	{
		List<Rectangle> bounds = new ArrayList<>();
		for (int component : plugin.getAlchemySpellComponents())
		{
			Widget spell = client.getWidget(component);
			if (spell != null && !spell.isHidden())
			{
				bounds.add(spell.getBounds());
			}
		}
		return bounds;
	}
}

package com.alchaligner;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.events.CanvasSizeChanged;
import net.runelite.api.events.ResizeableChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Alch Aligner",
	description = "Shows inventory slot click areas over the spellbook to line up alchemy casts",
	tags = {"alch", "alchemy", "high alch", "low alch", "magic", "spellbook", "inventory"}
)
public class AlchAlignerPlugin extends Plugin
{
	private static final int STANDARD_SPELLBOOK = 0;
	private static final int LOW_ALCHEMY_LEVEL = 21;
	private static final int HIGH_ALCHEMY_LEVEL = 55;

	@Inject
	private Client client;

	@Inject
	private AlchAlignerConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AlchAlignerOverlay overlay;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		overlay.clearSlots();
	}

	@Subscribe
	public void onCanvasSizeChanged(CanvasSizeChanged event)
	{
		// The side panel moves, so the remembered slot positions are stale until the inventory is shown again
		overlay.clearSlots();
	}

	@Subscribe
	public void onResizeableChanged(ResizeableChanged event)
	{
		overlay.clearSlots();
	}

	/**
	 * The alchemy spells the player can cast right now, empty if none.
	 * Requires the standard spellbook; High Level Alchemy from 55 Magic, and
	 * Low Level Alchemy from 21 Magic when enabled in the config.
	 */
	List<Integer> getAlchemySpellComponents()
	{
		List<Integer> spells = new ArrayList<>(2);
		if (client.getVarbitValue(VarbitID.SPELLBOOK) != STANDARD_SPELLBOOK)
		{
			return spells;
		}

		int magicLevel = client.getBoostedSkillLevel(Skill.MAGIC);
		if (magicLevel >= HIGH_ALCHEMY_LEVEL)
		{
			spells.add(InterfaceID.MagicSpellbook.HIGH_ALCHEMY);
		}
		if (config.lowAlchemy() && magicLevel >= LOW_ALCHEMY_LEVEL)
		{
			spells.add(InterfaceID.MagicSpellbook.LOW_ALCHEMY);
		}
		return spells;
	}

	@Provides
	AlchAlignerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AlchAlignerConfig.class);
	}
}

package com.alchaligner;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AlchAlignerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AlchAlignerPlugin.class);
		RuneLite.main(args);
	}
}
